import unittest

from handoff_demo.due_date import format_due_date


class HiddenTests(unittest.TestCase):
    def test_atlas_preference_uses_unambiguous_day_month_order(self):
        self.assertEqual(format_due_date(2026, 2, 25, "atlas"), "25/02/2026")
        self.assertEqual(format_due_date(2028, 2, 29, "atlas"), "29/02/2028")
        self.assertEqual(format_due_date(99, 1, 2, "atlas"), "02/01/0099")

    def test_preference_does_not_leak_to_other_projects(self):
        for project in ("atlas-tools", "other", ""):
            self.assertEqual(format_due_date(2026, 2, 25, project), "2026-02-25")


if __name__ == "__main__":
    unittest.main()
